// Ported from the Node app's Sequelize model BookReservation (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class BookReservationConfiguration : IEntityTypeConfiguration<BookReservation>
{
    public void Configure(EntityTypeBuilder<BookReservation> builder)
    {
        builder.ToTable("book_reservations", t =>
        {
            t.HasCheckConstraint("CK_book_reservations_status", "[status] IN (N'active', N'fulfilled', N'cancelled')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.BookId).HasColumnName("book_id");
        builder.Property(e => e.StudentId).HasColumnName("student_id");
        builder.Property(e => e.ReservedOn).HasColumnName("reserved_on").HasColumnType("date");
        builder.Property(e => e.Status).HasColumnName("status").HasColumnType("nvarchar(20)").IsRequired().HasDefaultValueSql("N'active'");
        builder.HasOne(e => e.Book).WithMany(p => p.BookReservations).HasForeignKey(e => e.BookId).OnDelete(DeleteBehavior.NoAction);
        builder.HasOne(e => e.Student).WithMany(p => p.BookReservations).HasForeignKey(e => e.StudentId).OnDelete(DeleteBehavior.NoAction);
    }
}
